"""
ASHES OF THE DEAD
Pixelated 2D side-view detective horror game
Single-file Pygame prototype.

Playable detective names:
    Julia
    May
    Yumi

Controls:
    A / D or Left / Right  - move
    Shift                  - run
    Space                  - jump
    Mouse                  - aim
    Left Mouse             - shoot
    E                      - interact / open / talk
    Q                      - use medkit
    I                      - inventory
    Esc                    - pause
    Enter / Space         - advance cutscenes
    R                      - restart after death

Install:
    pip install pygame

Run:
    python ashes_of_the_dead_pixelated.py

The game intentionally uses procedural pixel art so it does not require
external image files. It is designed as a foundation that can later be
split into sprites, animations, maps, sounds, and data files.
"""

import math
import random
import sys
from dataclasses import dataclass, field
from enum import Enum, auto

import os
os.environ.setdefault("SDL_AUDIODRIVER", "dummy")
import pygame

pygame.init()
try:
    pygame.mixer.init()
except pygame.error:
    pass

# ---------------------------------------------------------------------------
# Core constants
# ---------------------------------------------------------------------------

BASE_W = 320
BASE_H = 180
SCALE = 4
SCREEN_W = BASE_W * SCALE
SCREEN_H = BASE_H * SCALE
FPS = 60

TITLE = "ASHES OF THE DEAD"
NAMES = ["Julia", "May", "Yumi"]

WHITE = (235, 232, 220)
BLACK = (8, 9, 11)
GRAY = (90, 94, 98)
DARK = (18, 21, 24)
RED = (170, 58, 58)
GREEN = (76, 130, 86)
YELLOW = (205, 178, 91)
BLUE = (73, 105, 137)
SKIN = (196, 151, 116)
SKIN_LIGHT = (218, 174, 135)
HAIR = (43, 34, 31)
COAT = (64, 80, 95)
COAT_DARK = (38, 48, 58)
ZOMBIE = (86, 109, 88)
ZOMBIE_DARK = (43, 57, 47)
SMILER = (235, 233, 222)
SMILER_DARK = (22, 22, 23)
ROAD = (37, 39, 40)
GRASS = (34, 51, 37)
WATER = (35, 62, 76)
WOOD = (78, 57, 43)
RUST = (101, 55, 43)

# Low-resolution surfaces are used for deliberate pixelation.
screen = pygame.display.set_mode((SCREEN_W, SCREEN_H))
pygame.display.set_caption(TITLE)
canvas = pygame.Surface((BASE_W, BASE_H))
clock = pygame.time.Clock()

FONT = pygame.font.Font(None, 12)
FONT_SMALL = pygame.font.Font(None, 9)
FONT_BIG = pygame.font.Font(None, 20)
FONT_TITLE = pygame.font.Font(None, 28)


class GameState(Enum):
    TITLE = auto()
    NAME_SELECT = auto()
    CUTSCENE_FUNERAL = auto()
    ALCATRAZ = auto()
    SAN_FRANCISCO = auto()
    INFECTION_CORE = auto()
    SMILER_BOSS = auto()
    ENDING = auto()
    DEAD = auto()
    PAUSED = auto()


class ItemType(Enum):
    AMMO = auto()
    MEDKIT = auto()
    KEY = auto()
    NOTE = auto()
    CORE = auto()
    FOOD = auto()
    BATTERY = auto()


class EnemyType(Enum):
    WALKER = auto()
    RUNNER = auto()
    BRUTE = auto()
    SMILER = auto()


# ---------------------------------------------------------------------------
# Utility functions
# ---------------------------------------------------------------------------

def clamp(value, low, high):
    return max(low, min(high, value))


def lerp(a, b, t):
    return a + (b - a) * t


def distance(ax, ay, bx, by):
    return math.hypot(ax - bx, ay - by)


def draw_text(text, x, y, color=WHITE, font=FONT, center=False):
    image = font.render(str(text), False, color)
    rect = image.get_rect()
    if center:
        rect.center = (int(x), int(y))
    else:
        rect.topleft = (int(x), int(y))
    canvas.blit(image, rect)


def rect(x, y, w, h, color):
    pygame.draw.rect(canvas, color, pygame.Rect(int(x), int(y), int(w), int(h)))


def pixel_line(x1, y1, x2, y2, color, width=1):
    pygame.draw.line(canvas, color, (int(x1), int(y1)), (int(x2), int(y2)), width)


def pixel_circle(x, y, radius, color):
    pygame.draw.circle(canvas, color, (int(x), int(y)), int(radius))


def world_to_screen(x, y, camera_x):
    return int(x - camera_x), int(y)


# ---------------------------------------------------------------------------
# Procedural pixel-art helpers
# ---------------------------------------------------------------------------

def pixel_noise(surface, seed, amount, colors):
    rng = random.Random(seed)
    for _ in range(amount):
        x = rng.randrange(surface.get_width())
        y = rng.randrange(surface.get_height())
        c = rng.choice(colors)
        surface.set_at((x, y), c)


def draw_pixel_tree(x, y, scale=1):
    x = int(x)
    y = int(y)
    rect(x - 2 * scale, y - 14 * scale, 4 * scale, 14 * scale, WOOD)
    rect(x - 7 * scale, y - 20 * scale, 14 * scale, 8 * scale, GRASS)
    rect(x - 5 * scale, y - 24 * scale, 10 * scale, 6 * scale, GRASS)
    rect(x - 10 * scale, y - 17 * scale, 20 * scale, 7 * scale, GRASS)


def draw_grass_patch(x, y):
    pixel_line(x, y, x - 2, y - 5, (55, 80, 54))
    pixel_line(x + 2, y, x + 3, y - 4, (48, 75, 49))
    pixel_line(x + 4, y, x + 6, y - 3, (42, 67, 44))


def draw_car(x, y, damaged=False):
    body = RUST if damaged else (61, 65, 68)
    rect(x, y - 8, 38, 9, body)
    rect(x + 6, y - 14, 22, 7, body)
    rect(x + 10, y - 13, 7, 5, (29, 35, 39))
    rect(x + 19, y - 13, 7, 5, (29, 35, 39))
    pixel_circle(x + 8, y + 2, 4, (12, 13, 14))
    pixel_circle(x + 30, y + 2, 4, (12, 13, 14))
    if damaged:
        pixel_line(x + 4, y - 11, x + 18, y - 2, (48, 28, 24), 2)
        rect(x + 25, y - 7, 7, 3, (48, 28, 24))


def draw_locker(x, y):
    rect(x, y - 22, 13, 22, (54, 60, 63))
    rect(x + 2, y - 20, 9, 2, (93, 98, 100))
    rect(x + 9, y - 12, 2, 2, YELLOW)


def draw_chest(x, y):
    rect(x, y - 8, 17, 8, WOOD)
    rect(x + 1, y - 10, 15, 3, (105, 76, 55))
    rect(x + 7, y - 7, 3, 3, YELLOW)


def draw_grave(x, y, broken=False):
    rect(x - 1, y - 20, 3, 20, (91, 91, 86))
    rect(x - 7, y - 15, 15, 3, (91, 91, 86))
    if broken:
        pixel_line(x - 8, y - 20, x + 8, y - 3, (63, 63, 60), 2)


def draw_player_sprite(x, y, facing=1, walk_phase=0, wounded=False):
    # Hair
    pixel_circle(x, y - 30, 7, HAIR)
    rect(x - 6, y - 29, 12, 11, SKIN)
    # Face
    rect(x + (2 if facing > 0 else -4), y - 26, 2, 2, BLACK)
    # Body / detective coat
    rect(x - 6, y - 19, 12, 17, COAT)
    rect(x - 7, y - 16, 14, 3, COAT_DARK)
    # Arms
    arm_y = y - 12 + int(math.sin(walk_phase) * 2)
    rect(x - 10, arm_y, 4, 10, COAT)
    rect(x + 6, arm_y, 4, 10, COAT)
    # Hands
    rect(x - 10, arm_y + 9, 4, 3, SKIN_LIGHT)
    rect(x + 6, arm_y + 9, 4, 3, SKIN_LIGHT)
    # Legs
    leg_offset = int(math.sin(walk_phase) * 2)
    rect(x - 5 + leg_offset, y - 2, 4, 13, (28, 31, 35))
    rect(x + 1 - leg_offset, y - 2, 4, 13, (28, 31, 35))
    if wounded:
        rect(x - 7, y - 9, 14, 2, RED)


def draw_zombie_sprite(x, y, facing=1, phase=0, variant=0):
    skin = ZOMBIE if variant != 2 else (112, 93, 75)
    dark = ZOMBIE_DARK
    pixel_circle(x, y - 30, 7, skin)
    rect(x - 6, y - 22, 12, 18, dark)
    rect(x - 10, y - 18 + int(math.sin(phase) * 2), 4, 12, dark)
    rect(x + 6, y - 17 - int(math.sin(phase) * 2), 4, 12, dark)
    rect(x - 5, y - 3, 4, 13, (28, 29, 27))
    rect(x + 1, y - 3, 4, 13, (28, 29, 27))
    rect(x - 4, y - 32, 3, 3, RED)
    rect(x + 2, y - 32, 3, 3, RED)


def draw_smiler_sprite(x, y, phase=0):
    # Deliberately simple, unsettling pixel silhouette.
    pixel_circle(x, y - 32, 8, SMILER)
    rect(x - 7, y - 23, 14, 22, SMILER_DARK)
    rect(x - 10, y - 19, 4, 13, SMILER_DARK)
    rect(x + 6, y - 19, 4, 13, SMILER_DARK)
    rect(x - 5, y - 1, 4, 14, SMILER_DARK)
    rect(x + 1, y - 1, 4, 14, SMILER_DARK)
    pixel_circle(x - 3, y - 34, 2, BLACK)
    pixel_circle(x + 3, y - 34, 2, BLACK)
    # Smile
    pygame.draw.arc(
        canvas,
        BLACK,
        pygame.Rect(x - 6, y - 34, 12, 12),
        0.1,
        math.pi - 0.1,
        2,
    )
    if int(phase * 5) % 2 == 0:
        rect(x - 4, y - 29, 8, 2, BLACK)


# ---------------------------------------------------------------------------
# Data classes
# ---------------------------------------------------------------------------

@dataclass
class Item:
    x: float
    y: float
    item_type: ItemType
    amount: int = 1
    used: bool = False
    label: str = ""


@dataclass
class Bullet:
    x: float
    y: float
    vx: float
    vy: float
    damage: int = 1
    life: float = 1.0


@dataclass
class Particle:
    x: float
    y: float
    vx: float
    vy: float
    life: float
    color: tuple = WHITE
    size: int = 1


@dataclass
class Enemy:
    x: float
    y: float
    enemy_type: EnemyType = EnemyType.WALKER
    hp: int = 2
    speed: float = 18
    damage: int = 8
    attack_cooldown: float = 0
    phase: float = 0
    active: bool = True

    def update(self, game, dt):
        if not self.active:
            return
        self.phase += dt * 4
        dx = game.player.x - self.x
        dy = game.player.y - self.y
        d = max(0.001, math.hypot(dx, dy))

        if self.enemy_type == EnemyType.RUNNER:
            self.speed = 34
        elif self.enemy_type == EnemyType.BRUTE:
            self.speed = 11
        elif self.enemy_type == EnemyType.SMILER:
            self.speed = 22
        else:
            self.speed = 18

        if d > 22:
            self.x += dx / d * self.speed * dt
            self.y += dy / d * self.speed * dt

        self.attack_cooldown -= dt
        if d < 17 and self.attack_cooldown <= 0:
            if self.enemy_type == EnemyType.BRUTE:
                self.damage = 18
            elif self.enemy_type == EnemyType.SMILER:
                self.damage = 12
            else:
                self.damage = 8
            game.player.hp -= self.damage
            self.attack_cooldown = 0.9
            game.shake = 0.15

    def draw(self, camera_x):
        sx, sy = world_to_screen(self.x, self.y, camera_x)
        if self.enemy_type == EnemyType.SMILER:
            draw_smiler_sprite(sx, sy, self.phase)
        else:
            variant = 2 if self.enemy_type == EnemyType.BRUTE else 0
            draw_zombie_sprite(sx, sy, -1 if self.x > 0 else 1, self.phase, variant)


@dataclass
class Survivor:
    x: float
    y: float
    name: str
    dialogue_index: int = 0
    rescued: bool = False


@dataclass
class Player:
    name: str = "Julia"
    x: float = 80
    y: float = 132
    vx: float = 0
    vy: float = 0
    hp: int = 100
    max_hp: int = 100
    ammo: int = 18
    medkits: int = 1
    keys: int = 0
    notes: int = 0
    batteries: int = 0
    facing: int = 1
    grounded: bool = True
    running: bool = False
    shoot_cooldown: float = 0
    invulnerable: float = 0

    def update(self, game, dt):
        keys = pygame.key.get_pressed()
        move = 0
        if keys[pygame.K_a] or keys[pygame.K_LEFT]:
            move -= 1
        if keys[pygame.K_d] or keys[pygame.K_RIGHT]:
            move += 1

        self.running = bool(keys[pygame.K_LSHIFT] or keys[pygame.K_RSHIFT])
        speed = 54 if self.running else 34

        self.vx = move * speed
        if move:
            self.facing = move

        self.x += self.vx * dt
        self.x = clamp(self.x, 8, game.level_width - 8)

        if (keys[pygame.K_SPACE] or keys[pygame.K_UP]) and self.grounded:
            self.vy = -105
            self.grounded = False

        self.vy += 250 * dt
        self.y += self.vy * dt

        floor = 135
        if self.y >= floor:
            self.y = floor
            self.vy = 0
            self.grounded = True

        self.shoot_cooldown = max(0, self.shoot_cooldown - dt)
        self.invulnerable = max(0, self.invulnerable - dt)

    def shoot(self, game):
        if self.shoot_cooldown > 0 or self.ammo <= 0:
            return
        self.ammo -= 1
        self.shoot_cooldown = 0.20

        mx, my = pygame.mouse.get_pos()
        mx //= SCALE
        my //= SCALE
        wx = mx + game.camera_x
        wy = my

        angle = math.atan2(wy - (self.y - 18), wx - self.x)
        speed = 150

        game.bullets.append(
            Bullet(
                self.x + self.facing * 8,
                self.y - 18,
                math.cos(angle) * speed,
                math.sin(angle) * speed,
                1,
                1.0,
            )
        )

        for _ in range(4):
            game.particles.append(
                Particle(
                    self.x + self.facing * 10,
                    self.y - 18,
                    random.uniform(-15, 15),
                    random.uniform(-15, 15),
                    0.15,
                    YELLOW,
                    1,
                )
            )


# ---------------------------------------------------------------------------
# Level construction
# ---------------------------------------------------------------------------

class Level:
    def __init__(self, name, width, sky, ground):
        self.name = name
        self.width = width
        self.sky = sky
        self.ground = ground
        self.items = []
        self.enemies = []
        self.survivors = []
        self.decor = []
        self.exit_x = width - 20
        self.core_x = None
        self.build()

    def build(self):
        rng = random.Random(hash(self.name) & 0xFFFF)
        for i in range(self.width // 18):
            x = i * 18 + rng.randint(-4, 4)
            self.decor.append(("grass", x, 145))
        for i in range(14):
            x = rng.randint(20, self.width - 20)
            self.decor.append(("tree", x, 132))
        for i in range(5):
            x = rng.randint(30, self.width - 30)
            self.decor.append(("car", x, 137))

    def add_item(self, x, item_type, amount=1, label=""):
        self.items.append(Item(x, 132, item_type, amount, False, label))

    def add_enemy(self, x, enemy_type=EnemyType.WALKER):
        self.enemies.append(
            Enemy(
                x=x,
                y=135,
                enemy_type=enemy_type,
                hp=2 if enemy_type != EnemyType.BRUTE else 5,
            )
        )


def make_alcatraz():
    level = Level("Alcatraz", 760, (17, 23, 31), (31, 32, 34))
    level.add_item(155, ItemType.AMMO, 10, "Ammunition")
    level.add_item(285, ItemType.KEY, 1, "Old cell key")
    level.add_item(420, ItemType.MEDKIT, 1, "Medical supplies")
    level.add_item(545, ItemType.NOTE, 1, "Prison note")
    level.add_enemy(245, EnemyType.WALKER)
    level.add_enemy(365, EnemyType.WALKER)
    level.add_enemy(485, EnemyType.RUNNER)
    level.add_enemy(620, EnemyType.BRUTE)
    level.exit_x = 720
    return level


def make_san_francisco():
    level = Level("San Francisco", 920, (19, 28, 33), (33, 36, 38))
    level.add_item(180, ItemType.AMMO, 12, "Ammo box")
    level.add_item(360, ItemType.MEDKIT, 1, "First aid kit")
    level.add_item(540, ItemType.BATTERY, 1, "Radio battery")
    level.add_item(700, ItemType.NOTE, 1, "Detective report")
    level.survivors.append(Survivor(820, 135, "Eli"))
    for x in [260, 330, 450, 575, 650, 760]:
        level.add_enemy(x, EnemyType.WALKER)
    level.add_enemy(500, EnemyType.RUNNER)
    level.exit_x = 880
    return level


def make_core():
    level = Level("Infection Core", 980, (8, 10, 13), (25, 27, 29))
    level.add_item(250, ItemType.AMMO, 15, "Military ammunition")
    level.add_item(460, ItemType.MEDKIT, 1, "Field kit")
    level.add_item(650, ItemType.CORE, 1, "Infection core")
    for x in [300, 380, 470, 560, 690, 770, 850]:
        level.add_enemy(x, EnemyType.WALKER)
    level.add_enemy(600, EnemyType.BRUTE)
    level.core_x = 650
    level.exit_x = 930
    return level


